const U = new THREE.Vector3(-Math.cos(isoAz) * Math.sin(isoEl), Math.cos(isoEl), -Math.sin(isoAz) * Math.sin(isoEl)).normalize();
const CAMDIR = new THREE.Vector3(Math.cos(isoAz) * Math.cos(isoEl), Math.sin(isoEl), Math.sin(isoAz) * Math.cos(isoEl)).normalize();
