  makeLabel(stageName, '<i>y</i>', yTip.clone().addScaledVector(YD, 0.12 * scale), { fontSize: `${18 * scale}px` });
}

function lobeGeometry(length = 0.8, radius = 0.3, rings = 28, segs = 36) {
  const verts = [];
  const normals = [];
  const indices = [];
  for (let i = 0; i <= rings; i++) {
    const t = i / rings;
    const y = length * t;
    const taper = Math.sin(Math.PI * t);
    const skew = 0.45 + 0.7 * Math.sin(Math.PI * Math.min(t, 0.96));
    const r = radius * taper * skew * (1 - 0.12 * t);
    for (let j = 0; j <= segs; j++) {
      const a = 2 * Math.PI * j / segs;
      verts.push(r * Math.cos(a), y, r * Math.sin(a));
      normals.push(Math.cos(a), 0.25, Math.sin(a));
    }
  }
  for (let i = 0; i < rings; i++) {
    for (let j = 0; j < segs; j++) {
      const a = i * (segs + 1) + j;
      const b = a + segs + 1;
      indices.push(a, b, a + 1, b, b + 1, a + 1);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  g.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  g.computeBoundingSphere();
  return g;
}

function setLobe(mesh, origin, dir, length, radius) {
  mesh.geometry?.dispose?.();
  mesh.geometry = lobeGeometry(length, radius);
  mesh.position.copy(origin);
  orientYTo(mesh, dir);
  mesh.visible = length > 0.001 && radius > 0.001;
}

function addLobe(group, origin, dir, length, radius, color, opacity, stageName, contrib = null) {
  const mesh = new THREE.Mesh(lobeGeometry(length, radius), mat(color, opacity, { transparent: true, shininess: 82 }));
  mesh.position.copy(origin);
  orientYTo(mesh, dir);
  mesh.userData.stageName = stageName;
  mesh.userData.contrib = contrib;
  mesh.userData.contribAlpha = 1;
  group.add(mesh);
  if (contrib && atomicContribMeshes[contrib]) atomicContribMeshes[contrib].push(mesh);
  return mesh;
}

function addSphere(group, origin, radius, color, opacity, stageName, contrib = null) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, 48, 32), mat(color, opacity, { transparent: true, shininess: 70 }));
  mesh.position.copy(origin);
  mesh.userData.stageName = stageName;
  mesh.userData.contrib = contrib;
  mesh.userData.contribAlpha = 1;
  group.add(mesh);
  if (contrib && atomicContribMeshes[contrib]) atomicContribMeshes[contrib].push(mesh);
  return mesh;
}

function addOrbitalPanelLabel(stageName, text, origin) {
  makeLabel(stageName, text, origin.clone().addScaledVector(U, -1.15), { fontSize: '19px' });
}

function buildAtomicStage() {
  const g = stages.atomic;
  const origins = [
    vPanel(-1.25, 0.92),
    vPanel(1.25, 0.92),
    vPanel(-1.25, -1.05),
    vPanel(1.25, -1.05)
  ];
  origins.forEach(o => addTriad(g, o, 'atomic', 0.72));

  const s = addSphere(g, origins[0], 0.32, BLUE, 0.68, 'atomic', 's');
  registerInteractive(s, {
    title: 's orbital',
    tooltip: 'Spherical s orbital',
    body: 'The s orbital is the same in every direction. In sp³ hybridization it contributes an equal, same-sign part to each hybrid.'
  });
  const hi = addSphere(g, origins[0].clone().addScaledVector(R, -0.08).addScaledVector(U, 0.08), 0.13, 0xffffff, 0.22, 'atomic', 's');
  hi.material.depthWrite = false;
