  addOrbitalPanelLabel('atomic', '<i>p<sub>x</sub></i>', origins[1]);

  addLobe(g, origins[2], YD.clone().negate(), 0.62, 0.25, RED, 0.72, 'atomic', 'py');
  addLobe(g, origins[2], YD, 0.62, 0.25, PBLUE, 0.72, 'atomic', 'py');
  addOrbitalPanelLabel('atomic', '<i>p<sub>y</sub></i>', origins[2]);

  addLobe(g, origins[3], U, 0.62, 0.25, PBLUE, 0.72, 'atomic', 'pz');
