function makeGuide(group, origin, dir, length, stageName) {
  const m = lineMat(GUIDE, 0.65);
  const rod = cylinderBetween(
    origin.clone().addScaledVector(dir, -0.22),
    origin.clone().addScaledVector(dir, length),
    0.009,
    m
  );
  rod.userData.stageName = stageName;
  group.add(rod);
  return rod;
}

function makeHybridPair(group, origin, dir, stageName, signs, individual = false) {
  const guide = makeGuide(group, origin, dir, individual ? 1.02 : 1.12, stageName);
  const large = addLobe(group, origin, dir, individual ? 0.78 : 0.88, individual ? 0.29 : 0.31, ORANGE, 0.82, stageName);
  const back = addLobe(group, origin, dir.clone().negate(), individual ? 0.23 : 0.20, individual ? 0.10 : 0.085, GOLD, 0.72, stageName);
  const sphere = addSphere(group, origin, 0.16, GOLD, 0.0, stageName);
  sphere.material.userData.baseOpacity = 0.55;
  sphere.visible = false;
  const entry = { group, origin: origin.clone(), dir: dir.clone(), large, back, sphere, guide, signs, individual, stageName };
  (stageName === 'final' ? finalEntries : hybridEntries).push(entry);
  registerInteractive(large, {
    title: 'sp³ hybrid orbital',
    tooltip: 'Large orange hybrid lobe',
    body: 'A hybrid orbital combines s and p character. The s term makes a large forward lobe and a much smaller back-lobe.'
  });
  return entry;
}

