  makeHybridPair(g, origins[1], R, 'hybrids', [1, -1, -1], true);
  makeHybridPair(g, origins[2], YD.clone().negate(), 'hybrids', [-1, 1, -1], true);
  makeHybridPair(g, origins[3], U.clone().negate(), 'hybrids', [-1, -1, 1], true);

  const downStart = vPanel(2.55, -1.55);
  const downEnd = vPanel(2.55, -2.35);
  makeArrow(g, downStart, downEnd, GREY, 0.04, 0.17, 0.32, 0.85);
  makeLabel('hybrids', 'Gives a tetrahedral<br>arrangement', downStart.clone().addScaledVector(R, 0.78).addScaledVector(U, -0.34), {
    fontSize: '19px',
