buildAtomicStage();
buildHybridStage();
buildFinalStage();

function objectStageAlpha(obj) {
  let o = obj;
  while (o) {
    if (o === stages.atomic) return stageAlphas.atomic;
    if (o === stages.hybrids) return stageAlphas.hybrids;
    if (o === stages.final) return stageAlphas.final;
    o = o.parent;
  }
  return 1;
}

function updateMaterialOpacity() {
  scene.traverse(obj => {
    const mats = obj.material ? (Array.isArray(obj.material) ? obj.material : [obj.material]) : [];
    if (!mats.length) return;
    const sa = objectStageAlpha(obj);
    const ca = obj.userData.contribAlpha == null ? 1 : obj.userData.contribAlpha;
    for (const m of mats) {
      const base = m.userData.baseOpacity == null ? 1 : m.userData.baseOpacity;
      m.opacity = base * sa * ca;
      m.transparent = m.opacity < 0.999;
      if (m.opacity <= 0.002) obj.visible = false;
      else obj.visible = true;
    }
  });
  for (const e of stageLabelEntries) {
    const a = stageAlphas[e.stageName] || 0;
    e.div.style.opacity = String(a);
  }
}

function activeState() {
  return {
    s: document.getElementById('showS').checked,
    px: document.getElementById('showPx').checked,
    py: document.getElementById('showPy').checked,
    pz: document.getElementById('showPz').checked
  };
}

function dirFromSigns(signs, fallback) {
  const st = activeState();
  const v = new THREE.Vector3();
  if (st.px) v.addScaledVector(R, signs[0]);
  if (st.py) v.addScaledVector(YD, signs[1]);
  if (st.pz) v.addScaledVector(U, signs[2]);
  if (v.lengthSq() < 1e-5) return fallback.clone().normalize();
  return v.normalize();
}

function allContribOn() {
  const st = activeState();
  return st.s && st.px && st.py && st.pz;
}

function activePCount() {
  const st = activeState();
  return (st.px ? 1 : 0) + (st.py ? 1 : 0) + (st.pz ? 1 : 0);
}

function updateGuide(entry, dir, len) {
  const parent = entry.guide.parent;
  parent.remove(entry.guide);
  entry.guide.geometry?.dispose?.();
  entry.guide.material?.dispose?.();
  entry.guide = makeGuide(parent, entry.origin, dir, len, entry.stageName);
}

function updateHybridGeometry() {
  const st = activeState();
  for (const key of ['s', 'px', 'py', 'pz']) {
    for (const mesh of atomicContribMeshes[key]) mesh.userData.contribAlpha = st[key] ? 1 : 0.13;
  }

  const pCount = activePCount();
  const onlyS = st.s && pCount === 0;
  const noContrib = !st.s && pCount === 0;

  const idealFinal = [
    U.clone(),
    R.clone().multiplyScalar(1.08).addScaledVector(YD, 0.18).addScaledVector(U, -0.16).normalize(),
    U.clone().negate().addScaledVector(R, -0.08).addScaledVector(YD, -0.18).normalize(),
    R.clone().multiplyScalar(-0.9).addScaledVector(YD, -0.55).addScaledVector(U, -0.18).normalize()
  ];
  const idealIndividual = [U.clone(), R.clone(), YD.clone().negate(), U.clone().negate()];

  [...hybridEntries, ...finalEntries].forEach((entry, idx) => {
    const ideal = entry.stageName === 'final' ? idealFinal[finalEntries.indexOf(entry)] : idealIndividual[hybridEntries.indexOf(entry)];
    const dir = allContribOn() ? ideal : dirFromSigns(entry.signs, ideal);
    const stageScale = entry.individual ? 1 : 1.13;

    if (noContrib) {
      entry.large.visible = false;
      entry.back.visible = false;
      entry.sphere.visible = false;
      entry.guide.visible = false;
      return;
    }

    if (onlyS) {
      entry.large.visible = false;
      entry.back.visible = false;
      entry.sphere.visible = true;
      entry.sphere.position.copy(entry.origin);
      entry.guide.visible = false;
      return;
    }

    entry.large.visible = true;
    entry.back.visible = true;
    entry.sphere.visible = false;
    entry.guide.visible = true;

    const sBoost = st.s ? 1 : 0.72;
    const pBoost = pCount === 1 ? 0.86 : (pCount === 2 ? 0.92 : 1);
    const largeLen = (entry.individual ? 0.78 : 0.88) * stageScale * sBoost * pBoost;
    const largeRad = (entry.individual ? 0.29 : 0.31) * (st.s ? 1 : 0.82) * (pCount === 1 ? 0.88 : 1);
    const backLen = st.s ? (entry.individual ? 0.23 : 0.20) * stageScale : largeLen * 0.82;
    const backRad = st.s ? (entry.individual ? 0.10 : 0.085) : largeRad * 0.74;

    setLobe(entry.large, entry.origin, dir, largeLen, largeRad);
    setLobe(entry.back, entry.origin, dir.clone().negate(), backLen, backRad);
    updateGuide(entry, dir, entry.individual ? 1.02 : 1.22);
  });

  updateMaterialOpacity();
}

function setStage(name) {
  stageTargets.atomic = name === 'Atomic orbitals' ? 1 : 0;
  stageTargets.hybrids = name === 'Individual sp3 hybrids' ? 1 : 0;
  stageTargets.final = name === 'Tetrahedral arrangement' ? 1 : 0;
  document.getElementById('viewStage').value = name;
  controls.enableRotate = document.getElementById('orbitView').checked;
  document.getElementById('btnReset').style.display = '';
}

function fadeLoop() {
  for (const k of Object.keys(stageAlphas)) {
    stageAlphas[k] += (stageTargets[k] - stageAlphas[k]) * 0.18;
    if (Math.abs(stageTargets[k] - stageAlphas[k]) < 0.002) stageAlphas[k] = stageTargets[k];
  }
  updateMaterialOpacity();
  requestAnimationFrame(fadeLoop);
}

