  }
];

window.goToStep = function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  document.getElementById('showS').checked = step.state.showS;
  document.getElementById('showPx').checked = step.state.showPx;
  document.getElementById('showPy').checked = step.state.showPy;
  document.getElementById('showPz').checked = step.state.showPz;
  setStage(step.state.viewStage);
  updateHybridGeometry();
  document.getElementById('demoNarration').innerHTML = `<b>${step.title}</b><br>${step.narration}`;
};

document.getElementById('viewStage').addEventListener('change', e => setStage(e.target.value));
for (const id of ['showS', 'showPx', 'showPy', 'showPz']) {
  document.getElementById(id).addEventListener('change', updateHybridGeometry);
}
document.getElementById('orbitView').addEventListener('change', e => {
  controls.enableRotate = e.target.checked;
});
for (let i = 0; i < 4; i++) document.getElementById(`step${i}`).addEventListener('click', () => window.goToStep(i));

setStage('Atomic orbitals');
updateHybridGeometry();
fadeLoop();

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.72
});
controls.enableRotate = true;
window.goToStep(0);
