function mat(color, opacity = 1, opts = {}) {
  const m = new THREE.MeshPhongMaterial({
    color,
    transparent: opacity < 1 || opts.transparent,
    opacity,
    shininess: opts.shininess ?? 80,
    side: opts.side ?? THREE.DoubleSide,
    depthWrite: opacity > 0.76
  });
  m.userData.baseOpacity = opacity;
  return m;
}

function orientYTo(mesh, dir) {
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
}

function cylinderBetween(a, b, radius, material, radial = 16) {
  const mid = new THREE.Vector3().addVectors(a, b).multiplyScalar(0.5);
  const len = Math.max(a.distanceTo(b), 0.0001);
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, len, radial), material);
  mesh.position.copy(mid);
  orientYTo(mesh, new THREE.Vector3().subVectors(b, a));
  return mesh;
}

function coneArrow(end, dir, radius, length, material) {
  const mesh = new THREE.Mesh(new THREE.ConeGeometry(radius, length, 28), material);
  mesh.position.copy(end.clone().addScaledVector(dir.clone().normalize(), -length / 2));
  orientYTo(mesh, dir);
  return mesh;
}

function lineMaterial(color, opacity = 1) {
  const m = new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity });
  m.userData.baseOpacity = opacity;
  return m;
}

function makeArrow(group, start, end, color = AXIS_BLACK, radius = 0.01, headRadius = 0.055, headLen = 0.15, opacity = 1) {
  const dir = new THREE.Vector3().subVectors(end, start).normalize();
  const m = lineMaterial(color, opacity);
  const shaft = cylinderBetween(start, end.clone().addScaledVector(dir, -headLen * 0.78), radius, m, 14);
  const hm = lineMaterial(color, opacity);
  const head = coneArrow(end, dir, headRadius, headLen, hm);
  group.add(shaft, head);
  return [shaft, head];
}

