  const xBack = origin.clone().addScaledVector(R, -0.62 * scale);
  const zTip = origin.clone().addScaledVector(U, 0.88 * scale);
  const zBack = origin.clone().addScaledVector(U, -0.60 * scale);
  const yTip = origin.clone().addScaledVector(YD, 0.78 * scale);
  const yBack = origin.clone().addScaledVector(YD, -0.52 * scale);
  makeArrow(group, xBack, xTip, AXIS_BLACK, 0.0065 * scale, 0.045 * scale, 0.13 * scale);
  makeArrow(group, zBack, zTip, AXIS_BLACK, 0.0065 * scale, 0.045 * scale, 0.13 * scale);
  makeArrow(group, yBack, yTip, AXIS_BLACK, 0.0065 * scale, 0.045 * scale, 0.13 * scale);
  queueLabel(stageName, '<i>x</i>', xTip.clone().addScaledVector(R, 0.12 * scale), { fontSize: `${17 * scale}px` });
  queueLabel(stageName, '<i>z</i>', zTip.clone().addScaledVector(U, 0.12 * scale), { fontSize: `${17 * scale}px` });
  queueLabel(stageName, '<i>y</i>', yTip.clone().addScaledVector(YD, 0.12 * scale), { fontSize: `${17 * scale}px` });
