function roundedLobeGeometry(length = 0.72, radius = 0.28, rings = 52, segs = 64) {
  const verts = [];
  const indices = [];
  for (let i = 0; i <= rings; i++) {
    const t = i / rings;
    const y = length * t;
    const bulb = Math.pow(Math.sin(Math.PI * t), 0.62);
    const fullness = 0.64 + 0.56 * Math.sin(Math.PI * Math.min(t, 0.96));
    const frontRound = 1 - 0.08 * t;
    const r = radius * bulb * fullness * frontRound;
    for (let j = 0; j <= segs; j++) {
      const a = 2 * Math.PI * j / segs;
      verts.push(r * Math.cos(a), y, r * Math.sin(a));
    }
  }
  for (let i = 0; i < rings; i++) {
    for (let j = 0; j < segs; j++) {
      const a = i * (segs + 1) + j;
      const b = a + segs + 1;
      indices.push(a, b, a + 1, b, b + 1, a + 1);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  g.computeBoundingSphere();
  return g;
}

