    pz: document.getElementById('showPz').checked
  };
}

function activePCount(st = activeState()) {
  return (st.px ? 1 : 0) + (st.py ? 1 : 0) + (st.pz ? 1 : 0);
}

function allContribOn() {
  const st = activeState();
  return st.s && st.px && st.py && st.pz;
}

function dirFromSigns(signs, fallback) {
  const st = activeState();
  const v = new THREE.Vector3();
  if (st.px) v.addScaledVector(R, signs[0]);
  if (st.py) v.addScaledVector(YD, signs[1]);
  if (st.pz) v.addScaledVector(U, signs[2]);
  if (v.lengthSq() < 1e-5) return fallback.clone().normalize();
  return v.normalize();
}

function replaceGuide(entry, dir, len) {
  const parent = entry.guide.parent;
  parent.remove(entry.guide);
  entry.guide.geometry?.dispose?.();
  if (entry.guide.material) entry.guide.material.dispose?.();
  entry.guide = makeGuide(parent, entry.origin, dir, len, entry.stageName);
}

function updateHybridGeometry() {
  const st = activeState();
  for (const key of ['s', 'px', 'py', 'pz']) {
    for (const mesh of atomicContribMeshes[key]) mesh.userData.contribAlpha = st[key] ? 1 : 0.16;
  }

  const pCount = activePCount(st);
  const onlyS = st.s && pCount === 0;
  const noContrib = !st.s && pCount === 0;

  const idealIndividual = [
    U.clone(),
    R.clone(),
    R.clone().negate().addScaledVector(YD, -0.30).normalize(),
    U.clone().negate()
  ];
  const idealFinal = [
    U.clone(),
    R.clone().addScaledVector(YD, 0.10).addScaledVector(U, -0.03).normalize(),
    U.clone().negate().addScaledVector(YD, -0.12).addScaledVector(R, -0.08).normalize(),
    R.clone().negate().multiplyScalar(0.82).addScaledVector(U, -0.18).addScaledVector(YD, -0.45).normalize()
  ];

  [...hybridEntries, ...finalEntries].forEach(entry => {
    const list = entry.stageName === 'final' ? finalEntries : hybridEntries;
    const ideal = entry.stageName === 'final' ? idealFinal[list.indexOf(entry)] : idealIndividual[list.indexOf(entry)];
    const dir = allContribOn() ? ideal : dirFromSigns(entry.signs, ideal);

    if (noContrib) {
      entry.large.userData.hiddenByContrib = true;
      entry.back.userData.hiddenByContrib = true;
      entry.sphere.userData.hiddenByContrib = true;
      entry.guide.userData.hiddenByContrib = true;
      return;
    }

    if (onlyS) {
      entry.large.userData.hiddenByContrib = true;
      entry.back.userData.hiddenByContrib = true;
      entry.sphere.userData.hiddenByContrib = false;
      entry.guide.userData.hiddenByContrib = true;
      entry.sphere.position.copy(entry.origin);
      return;
    }

    entry.large.userData.hiddenByContrib = false;
    entry.back.userData.hiddenByContrib = false;
    entry.sphere.userData.hiddenByContrib = true;
    entry.guide.userData.hiddenByContrib = false;

    const baseLen = entry.individual ? 0.63 : 0.68;
    const baseRad = entry.individual ? 0.22 : 0.24;
    const sBoost = st.s ? 1 : 0.78;
    const pBoost = pCount === 1 ? 0.88 : (pCount === 2 ? 0.94 : 1);
    const largeLen = baseLen * sBoost * pBoost;
    const largeRad = baseRad * (st.s ? 1 : 0.86) * (pCount === 1 ? 0.90 : 1);
    const backLen = st.s ? (entry.individual ? 0.16 : 0.15) : largeLen * 0.82;
    const backRad = st.s ? (entry.individual ? 0.060 : 0.055) : largeRad * 0.72;

    setLobe(entry.large, entry.origin, dir, largeLen, largeRad);
    setLobe(entry.back, entry.origin, dir.clone().negate(), backLen, backRad);
    replaceGuide(entry, dir, entry.individual ? 0.78 : 0.86);
  });

  updateMaterialOpacity();
}

function setMode(mode) {
  document.getElementById('viewStage').value = mode;
  if (mode === 'all') {
    stageTargets.atomic = 1; stageTargets.hybrids = 1; stageTargets.final = 1; stageTargets.flow = 1;
    setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.90, target: [-0.55, -0.16, 0] });
